import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { transform } from "esbuild";

const gameRoot = join(process.cwd(), "public", "game", "js");
const sourceFiles = [
  "vendor/jquery.min.js",
  "vendor/detectmobilebrowser.js",
  "vendor/createjs.min.js",
  "vendor/TweenMax.min.js",
  "vendor/js.cookie.js",
  "plugins.js",
  "sound.js",
  "asset-manifest.js",
  "audio-loader.js",
  "deferred-assets.js",
  "canvas.js",
  "levels.js",
  "liquid-accessibility.js",
  "daily-challenge.js",
  "player-progress.js",
  "gameplay-assists.js",
  "game.js",
  "mobile.js",
  "main.js",
  "loader.js",
  "init.js",
];

const sourceChunks = await Promise.all(
  sourceFiles.map(async (file) => {
    const source = await readFile(join(gameRoot, file), "utf8");
    return `\n/* ${file} */\n${source}\n`;
  }),
);

// Keep global identifiers intact because this legacy CreateJS game shares
// functions across files. Whitespace and syntax minification are still safe.
const result = await transform(sourceChunks.join(";\n"), {
  legalComments: "none",
  minifyIdentifiers: false,
  minifySyntax: true,
  minifyWhitespace: true,
  target: "es2017",
});

const outputPath = join(gameRoot, "game.bundle.min.js");
await writeFile(outputPath, `/* Generated by scripts/build-game-bundle.mjs. */\n${result.code}`, "utf8");
console.log(`Built ${outputPath} from ${sourceFiles.length} source files.`);
